"use client";

import { useMemo, useRef, useState, type Dispatch, type SetStateAction } from "react";
import { CollapsibleSection } from "@/components/ui/collapsible";
import { categories } from "@/data/categories";
import { redactarRazonamientoProcesal, resolveAuthorityFromFacts, resolveDrugOutcome, resolvePublicSafetyOutcome, resolveWeaponOutcome, seguridadPublica, seguridadPublicaBlockDescription, seguridadPublicaBlockLabel, seguridadPublicaCategoryId, seguridadPublicaConceptos, type AuthorityFacts, type AuthorityOutcome, type DrugOutcome, type ProcessualInput, type PublicConcept, type PublicSafetyFacts, type PublicSafetyOutcome, type PublicSecurityBlock, type RazonamientoProcesal, type RelationalAnswer, type WeaponConduct, type WeaponContextInput, type WeaponObjectInput, type WeaponOutcome, type SustanciaObservada } from "@/data/seguridad-publica";
import { resolvePatrimonyOutcome, type PatrimonyFacts, type PatrimonyOutcome } from "@/data/patrimonio";
import { invertBooleanAnswer } from "@/data/boolean-answer";
import { obtenerReferenciaProcesal, type UsoReferenciaProcesal } from "@/data/referencias-procesales";
import { catalogoPenal, type SupuestoPenalId, type SupuestoPenal } from "@/data/catalogo-penal";
import { transformarMarcoPenal, type RegimenPenas } from "@/data/gravedad-penal";

type Props = { block: PublicSecurityBlock; initialConceptId?: string; onBack: () => void };
export type ProcessualFactsForm = Omit<ProcessualInput, "flagrante">;
const publicSecurityBlockIcon = (block: PublicSecurityBlock) => categories.find((category) => category.id === seguridadPublicaCategoryId(block))?.icono ?? "🛡️";
const publicSecurityConceptIcon = (conceptId: string) => seguridadPublicaConceptos.find((concept) => concept.id === conceptId)?.icono ?? "🧭";
export const hasProcessualAnswer = (flagrante: boolean | undefined, facts: ProcessualFactsForm, minor = false, complaintRequired = false) => facts.autorMayorEdad === false || facts.autorMayorEdad === true && (!complaintRequired || facts.denunciaOQuerella !== undefined) && (minor
  ? facts.domicilioConocido === true || facts.domicilioConocido === false && facts.fianzaBastante !== undefined
  : flagrante === true || flagrante === false && facts.indiciosHechoSuficientes !== undefined && (facts.indiciosHechoSuficientes === false || facts.indiciosParticipacionSuficientes !== undefined && (facts.indiciosParticipacionSuficientes === false || [facts.intentoFugaElusion, facts.identidadODomicilioNoVerificables, facts.riesgoOcultacionPruebas, facts.riesgoConcretoVictimaTestigos].every((value) => value !== undefined))));
const processualInput = (flagrante: boolean | undefined, facts: ProcessualFactsForm): ProcessualInput => ({ flagrante, ...facts });

export function SeguridadPublicaView({ block, initialConceptId, onBack }: Props) {
  const [activeBlock, setActiveBlock] = useState<PublicSecurityBlock>(block);
  const [selectedId, setSelectedId] = useState<string | undefined>(initialConceptId);
  const [query, setQuery] = useState("");
  const [facts, setFacts] = useState<PublicSafetyFacts>({});
  const blockConcepts = useMemo(() => seguridadPublicaConceptos.filter((concept) => concept.bloque === activeBlock), [activeBlock]);
  const selected = blockConcepts.find((concept) => concept.id === selectedId);
  const matches = useMemo(() => {
    const q = normalise(query);
    return q ? blockConcepts.filter((concept) => normalise([concept.titulo, ...concept.sinonimos].join(" ")).includes(q)) : [];
  }, [blockConcepts, query]);
  const choose = (id: string) => { const target = seguridadPublicaConceptos.find((concept) => concept.id === id); if (target) { setActiveBlock(target.bloque); setSelectedId(id); } setQuery(""); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const blockIcon = publicSecurityBlockIcon(activeBlock);
  if (selected) return <ConceptSheet concept={selected} facts={facts} setFacts={setFacts} onNavigate={choose} onBack={() => setSelectedId(undefined)} />;
  return <section className="sp-view">
    <div className="sp-heading"><div><span className="kicker">{seguridadPublica.titulo.toUpperCase()}</span><h2 className="icon-heading"><span className="heading-icon" aria-hidden="true">{blockIcon}</span>{seguridadPublicaBlockLabel(activeBlock)}</h2><p>{seguridadPublicaBlockDescription[activeBlock]}</p></div><button className="alcohol-back" onClick={onBack}>← Volver a Seguridad Pública</button></div>
    <section className="sp-search"><label htmlFor="public-security-search">Buscar situación</label><input id="public-security-search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Ej.: porro, no se identifica, navaja…" autoComplete="off" />{query && <div className="sp-search-results">{matches.length ? matches.map((concept) => <button key={concept.id} onClick={() => choose(concept.id)}><span className="sp-search-icon" aria-hidden="true">{concept.icono}</span><span><strong>{concept.titulo}</strong><small>{seguridadPublicaBlockLabel(concept.bloque)}</small></span></button>) : <p>Sin concepto operativo coincidente.</p>}</div>}</section>
    <section className="sp-block"><div className="sp-block-heading"><span aria-hidden="true">{blockIcon}</span><h3>{seguridadPublicaBlockLabel(activeBlock)}</h3></div><div className="sp-concept-grid">{blockConcepts.map((concept) => <button key={concept.id} onClick={() => choose(concept.id)}><span className="sp-concept-icon" aria-hidden="true">{concept.icono}</span><span><strong>{concept.titulo}</strong><small>{concept.resultado}</small></span><b aria-hidden="true">›</b></button>)}</div></section>
  </section>;
}

function ConceptSheet({ concept, facts, setFacts, onNavigate, onBack }: { concept: PublicConcept; facts: PublicSafetyFacts; setFacts: Dispatch<SetStateAction<PublicSafetyFacts>>; onNavigate: (id: string) => void; onBack: () => void }) {
  const sheetRef = useRef<HTMLElement>(null);
  const [copied, setCopied] = useState(false);
  const copySummary = async () => {
    const text = sheetRef.current?.innerText;
    if (!text) return;
    await navigator.clipboard.writeText(text);
    setCopied(true);
    window.setTimeout(() => setCopied(false), 1600);
  };
  return <section className="sp-view sp-view-with-actions"><button className="back sp-desktop-back" onClick={onBack}>← Volver a {seguridadPublicaBlockLabel(concept.bloque)}</button><article className="sp-sheet" ref={sheetRef}><header><span className="kicker">{seguridadPublicaBlockLabel(concept.bloque).toUpperCase()}</span><h2 className="icon-heading"><span className="heading-icon" aria-hidden="true">{concept.icono}</span>{concept.titulo}</h2><p>{concept.resultado}</p></header>{concept.id === "drogas_trafico" ? <DrugDecision /> : concept.id === "patrimonio" ? <PatrimonyDecision facts={facts} onNavigate={onNavigate} /> : ["armas_blancas", "objetos_peligrosos"].includes(concept.id) ? <WeaponDecision key={concept.id} concept={concept} facts={facts} /> : ["desobediencia", "resistencia", "amenazas"].includes(concept.id) ? <AuthorityDecision concept={concept} /> : concept.id === "atentado" ? <AtentadoConcept concept={concept} /> : isIncidentConcept(concept.id) ? <IncidentDecision concept={concept} facts={facts} setFacts={setFacts} onNavigate={onNavigate} /> : <StaticConcept concept={concept} />}</article><nav className="sp-mobile-actions" aria-label="Acciones principales"><button onClick={onBack}>← Volver</button><button className="primary" onClick={copySummary}>{copied ? "✓ Copiado" : "Copiar resumen"}</button></nav></section>;
}

function StaticConcept({ concept }: { concept: PublicConcept }) {
  return <><OperationalSection title="Qué comprobar" items={concept.comprobar} /><ResultCard title={concept.calificacion?.startsWith("DELITO") ? "POSIBLE DELITO" : "INFRACCIÓN"} norma={concept.norma} clasificacion={concept.calificacion} range={concept.rango} text={concept.resultado} /><OperationalSection title="Actuación policial" items={concept.actuacion ?? []} />{concept.id === "identificacion" && <div className="sp-highlight neutral"><strong>TRASLADO IDENTIFICATIVO</strong><p>El traslado a dependencias a efectos exclusivos de identificación conforme al art. 16 LO 4/2015 no constituye una detención penal.</p></div>}{concept.competencia && <OperationalSection title="Competencia" items={[concept.competencia]} />}{concept.bloque === "Drogas" && <CommonProcessual showSubstance />}<LegalFoundation normas={[concept.norma, ...(concept.fuentes ?? [])]} detalle={concept.frontera} /></>;
}

function AtentadoConcept({ concept }: { concept: PublicConcept }) {
  return <AuthorityDecision concept={concept} />;
}

function DrugDecision() {
  const [status, setStatus] = useState<"sin" | "duda" | "venta">(); const [substance, setSubstance] = useState<SustanciaObservada>("desconocida"); const [indicators, setIndicators] = useState<string[]>([]); const [flagrante, setFlagrante] = useState<boolean>(); const [processFacts, setProcessFacts] = useState<ProcessualFactsForm>({});
  const processual = processualInput(flagrante, processFacts);
  const result: DrugOutcome | null = !status || status === "sin" ? null : status === "duda" ? resolveDrugOutcome({ ventaObservada: false, indiciosSuficientes: false, sustancia: substance, ...processual }) : resolveDrugOutcome({ ventaObservada: true, indiciosSuficientes: true, sustancia: substance, ...processual });
  const complaintRequired = result?.procedibilidadPenal === "denuncia" || result?.procedibilidadPenal === "sexual_191";
  return <><OperationalSection title="Qué comprobar" items={seguridadPublicaConceptos.find((item) => item.id === "drogas_trafico")?.comprobar ?? []} /><fieldset className="sp-choice"><legend>¿Se observa venta, entrega o suministro a tercero?</legend><label><input type="radio" checked={status === "sin"} onChange={() => setStatus("sin")} /> No se observa entrega ni se conocen otros datos de distribución</label><label><input type="radio" checked={status === "duda"} onChange={() => setStatus("duda")} /> Constan envoltorios, dinero, mensajes u otros datos por comprobar</label><label><input type="radio" checked={status === "venta"} onChange={() => setStatus("venta")} /> Sí; se observa el intercambio y su vinculación con esta persona</label>{status === "venta" && <label className="sp-subchoice">Sustancia identificada mediante comprobación disponible <select value={substance} onChange={(event) => setSubstance(event.target.value as SustanciaObservada)}><option value="desconocida">Sin identificar o solo apariencia; pendiente de análisis</option><option value="cocaina">Cocaína</option><option value="heroina">Heroína</option><option value="mdma">MDMA</option><option value="anfetamina">Anfetamina / metanfetamina</option><option value="lsd">LSD</option><option value="cannabis">Cannabis / hachís</option></select></label>}</fieldset>{status === "venta" && <ProcessualControls flagrante={flagrante} setFlagrante={setFlagrante} facts={processFacts} setFacts={setProcessFacts} complaintRequired={complaintRequired} />}{status === "duda" && <fieldset className="sp-choice"><legend>Indicios concretos a documentar</legend>{trafficIndicators.map((indicator) => <label key={indicator}><input type="checkbox" checked={indicators.includes(indicator)} onChange={() => setIndicators((current) => current.includes(indicator) ? current.filter((item) => item !== indicator) : [...current, indicator])} /> {indicator}</label>)}</fieldset>}{!status ? <section className="sp-section"><h3>Datos de la intervención</h3><p>Indica qué conducta se observa o qué datos concretos constan.</p><h3>Actuación inmediata</h3><ul><li>Identificar a las personas implicadas.</li><li>Documentar y preservar sustancia, testigos y soportes disponibles.</li></ul></section> : status === "sin" ? <section className="sp-section"><h3>Sin tráfico constatado</h3><p>Documentar los hechos comprobados. Si hubo consumo o tenencia en lugar público, examinar ese supuesto por separado antes de formular denuncia administrativa.</p></section> : result && <><ResolvedOutcome result={result} drug showProcessual />{status === "duda" && <OperationalSection title="Indicios concretos presentes" items={indicators.length ? indicators : ["Marca los indicios observados antes de documentar y coordinar la continuación con CNP."]} />}</>}</>;
}

const incidentConceptIds = ["violencia_relacional", "agresiones_lesiones", "agresiones_sexuales", "peleas_rinas", "amenazas_coacciones"];
const isIncidentConcept = (id: string) => incidentConceptIds.includes(id);

function IncidentDecision({ concept, facts, setFacts, onNavigate }: { concept: PublicConcept; facts: PublicSafetyFacts; setFacts: Dispatch<SetStateAction<PublicSafetyFacts>>; onNavigate: (id: string) => void }) {
  const [flagrante, setFlagrante] = useState<boolean>();
  const [processFacts, setProcessFacts] = useState<ProcessualFactsForm>({});
  const processual = processualInput(flagrante, processFacts);
  const set = <K extends keyof PublicSafetyFacts>(key: K, value: PublicSafetyFacts[K]) => setFacts((current) => ({ ...current, [key]: value }));
  const toggleRelationEvent = (value: NonNullable<PublicSafetyFacts["hechosRelacion"]>[number]) => setFacts((current) => ({ ...current, hechosRelacion: current.hechosRelacion?.includes(value) ? current.hechosRelacion.filter((item) => item !== value) : [...(current.hechosRelacion ?? []), value] }));
  const result = resolvePublicSafetyOutcome(concept.id, facts, processual);
  const hasProcessualOutput = Boolean(result.procesal);
  const fixedMinorOffence = result.procesal?.escenarioProcesal === "DELITO LEVE";
  const needsProcessualFacts = hasProcessualOutput && facts.autorMayorEdad !== false;
  const complaintRequired = result.resultados.some((item) => item.procedibilidadPenal === "denuncia" || item.procedibilidadPenal === "sexual_191");
  const sexualContext = concept.id === "agresiones_sexuales" || facts.hechosRelacion?.includes("sexual");
  const showComplaintQuestion = sexualContext && facts.actoSexualNoConsentido === true;
  const protectedRelation = facts.parejaExpareja === "si" || facts.relacionFamiliar === "si" || facts.parejaExpareja === "no" && facts.relacionFamiliar === "no" && facts.convivencia === "si";
  const hasSavedRelationalContext = [facts.parejaExpareja, facts.relacionFamiliar, facts.convivencia, facts.sexoAutor, facts.sexoVictima].some((value) => value !== undefined);
  return <>
    <OperationalSection title="Qué comprobar" items={concept.comprobar} />
    {hasSavedRelationalContext && concept.id !== "violencia_relacional" && <div className="sp-highlight neutral"><strong>CONTEXTO RELACIONAL CONSERVADO</strong><p>Los hechos ya indicados se reutilizan al conectar con otros bloques; solo se pedirán los datos que falten y puedan cambiar la salida.</p></div>}
    {concept.id === "violencia_relacional" && <>
      <ProtectedRelationshipQuestions facts={facts} set={set} />
      <ToggleQuestion legend="¿Había menores presentes durante los hechos?" value={facts.presenciaMenores} onChange={(value) => set("presenciaMenores", value)} />
      <ToggleQuestion legend="¿El hecho tuvo lugar en el domicilio común o en el domicilio de la víctima?" value={facts.domicilioComunOVictima} onChange={(value) => set("domicilioComunOVictima", value)} />
      <fieldset className="sp-choice"><legend>¿Qué conductas se observan o refieren además?</legend>{relationEvents.map(([value, label]) => <label key={value}><input type="checkbox" checked={facts.hechosRelacion?.includes(value as NonNullable<PublicSafetyFacts["hechosRelacion"]>[number]) ?? false} onChange={() => toggleRelationEvent(value as NonNullable<PublicSafetyFacts["hechosRelacion"]>[number])} /> {label}</label>)}</fieldset>
      {facts.hechosRelacion?.some((event) => ["agresion", "amenazas", "coacciones", "sexual"].includes(event)) && <ToggleQuestion legend="¿Se utilizó un arma u objeto peligroso en alguno de estos hechos?" value={facts.armaUtilizada} onChange={(value) => set("armaUtilizada", value)} />}
      <ToggleQuestion legend="¿Se refieren episodios anteriores de violencia física o psíquica?" value={facts.episodiosPrevios} onChange={(value) => set("episodiosPrevios", value)} />
      {facts.episodiosPrevios && <ToggleQuestion legend="¿Se pueden describir varios episodios anteriores, sus fechas y las personas afectadas?" value={facts.habitualidadDocumentada} onChange={(value) => set("habitualidadDocumentada", value)} />}
    {facts.hechosRelacion?.includes("quebrantamiento") && <><ToggleQuestion legend="¿Consta una medida o pena vigente y conocida por la persona?" value={facts.medidaVigenteConocida} onChange={(value) => set("medidaVigenteConocida", value)} />{facts.medidaVigenteConocida && <><ToggleQuestion legend="¿Se documenta un incumplimiento concreto de esa resolución?" value={facts.incumplimientoMedida} onChange={(value) => { set("incumplimientoMedida", value); set("medidaQuebrantada", value); }} /><ToggleQuestion legend="¿Se manipuló un dispositivo técnico de control?" value={facts.dispositivoControlManipulado} onChange={(value) => set("dispositivoControlManipulado", value)} />{!facts.dispositivoControlManipulado && <><ToggleQuestion legend="¿La medida prohíbe acercarse o comunicarse con pareja, expareja, familiar o persona del mismo núcleo familiar?" value={facts.medidaRelacion1732} onChange={(value) => set("medidaRelacion1732", value)} />{facts.medidaRelacion1732 === false && <ToggleQuestion legend="¿La persona estaba privada de libertad?" value={facts.privadoLibertad} onChange={(value) => set("privadoLibertad", value)} />}</>}</>}</>}
      {facts.hechosRelacion?.includes("vejaciones") && <ToggleQuestion legend="¿Constan insultos o actos concretos de humillación dirigidos a la víctima?" value={facts.vejacionInjuriaLeve} onChange={(value) => set("vejacionInjuriaLeve", value)} />}
      {facts.hechosRelacion?.includes("amenazas") && <><ChoiceQuestion legend="¿Qué mal se anuncia?" value={facts.malAnunciado} options={relationThreatHarmOptions} onChange={(value) => set("malAnunciado", value as PublicSafetyFacts["malAnunciado"])} />{facts.malAnunciado !== "no_delictivo" && <><ToggleQuestion legend="¿Se impone una condición para no causar el mal?" value={facts.condicionImpuesta} onChange={(value) => set("condicionImpuesta", value)} />{facts.condicionImpuesta && <ToggleQuestion legend="¿Se consiguió el propósito de la condición?" value={facts.propositoConseguido} onChange={(value) => set("propositoConseguido", value)} />}</>}{facts.malAnunciado === "no_delictivo" && <><ToggleQuestion legend="¿Se impuso una condición para no causar ese mal?" value={facts.condicionImpuesta} onChange={(value) => set("condicionImpuesta", value)} />{facts.condicionImpuesta && <><ToggleQuestion legend="¿Exigía cumplir una obligación que consta en documento o reconoce la persona afectada?" value={facts.condicionConductaDebida} onChange={(value) => set("condicionConductaDebida", value)} /><ToggleQuestion legend="¿Se consiguió el propósito de la condición?" value={facts.propositoConseguido} onChange={(value) => set("propositoConseguido", value)} /></>}</>}{facts.malAnunciado === "menor_entidad" && protectedRelation && <ToggleQuestion legend="¿Se usó arma u otro instrumento peligroso?" value={facts.medioPeligroso} onChange={(value) => set("medioPeligroso", value)} />}</>}
      {facts.hechosRelacion?.includes("coacciones") && <><ChoiceQuestion legend="¿Qué conducta concreta se observa o refiere?" value={facts.coaccionEntidad} options={coactionOptions} onChange={(value) => set("coaccionEntidad", value as PublicSafetyFacts["coaccionEntidad"])} /><ToggleQuestion legend="¿Se usó arma u otro instrumento peligroso?" value={facts.medioPeligroso} onChange={(value) => set("medioPeligroso", value)} /></>}
      {facts.hechosRelacion?.includes("acoso") && <><ChoiceQuestion legend="¿Qué conducta reiterada se documenta?" value={facts.conductaAcoso} options={harassmentOptions} onChange={(value) => set("conductaAcoso", value as PublicSafetyFacts["conductaAcoso"])} /><ToggleQuestion legend="¿La conducta fue insistente y reiterada sin autorización?" value={facts.acosoReiterado} onChange={(value) => set("acosoReiterado", value)} /><ToggleQuestion legend="¿Alteró el desarrollo normal de la vida cotidiana?" value={facts.alteracionVidaCotidiana} onChange={(value) => set("alteracionVidaCotidiana", value)} /><ToggleQuestion legend="¿Consta edad, enfermedad o circunstancia que le dificulta protegerse?" value={facts.vulnerabilidadEspecial} onChange={(value) => set("vulnerabilidadEspecial", value)} /></>}
      {facts.hechosRelacion?.includes("sexual") && <><ToggleQuestion legend="¿Se refiere un acto sexual no consentido?" value={facts.actoSexualNoConsentido} onChange={(value) => set("actoSexualNoConsentido", value)} />{facts.actoSexualNoConsentido && <><ToggleQuestion legend="¿La víctima es menor de 16 años?" value={facts.menorDieciseis} onChange={(value) => set("menorDieciseis", value)} /><ToggleQuestion legend="¿El presunto autor tenía 18 años o más?" value={facts.autorMayorEdad} onChange={(value) => { set("autorMayorEdad", value); setProcessFacts((current) => ({ ...current, autorMayorEdad: value })); }} /><ChoiceQuestion legend="¿Qué conducta sexual concreta se documenta?" value={facts.conductaSexual} options={sexualConductOptions} onChange={(value) => set("conductaSexual", value as PublicSafetyFacts["conductaSexual"])} />{facts.conductaSexual === "hacer_presenciar" && <ToggleQuestion legend="¿La persona que sufrió los actos presenciados refiere que se realizaron contra su voluntad o mediante fuerza o amenazas?" value={facts.actosPresenciadosDelictivos} onChange={(value) => set("actosPresenciadosDelictivos", value)} />}{facts.conductaSexual === "contacto_tic" && <><ToggleQuestion legend="¿Consta propuesta de encuentro y actos materiales de acercamiento?" value={facts.propuestaEncuentroYAcercamiento} onChange={(value) => set("propuestaEncuentroYAcercamiento", value)} /><ToggleQuestion legend="¿Constan actos dirigidos a embaucar para obtener material o imágenes pornográficas?" value={facts.embaucarMaterialPornografico} onChange={(value) => set("embaucarMaterialPornografico", value)} /></>}{facts.conductaSexual === "acto_fisico" && <><ToggleQuestion legend="¿Consta acceso carnal o introducción de miembros u objetos?" value={facts.penetracion} onChange={(value) => set("penetracion", value)} /><ToggleQuestion legend="¿Consta violencia o intimidación?" value={facts.violenciaIntimidacion} onChange={(value) => set("violenciaIntimidacion", value)} /><ToggleQuestion legend="¿La víctima estaba inconsciente o no podía reaccionar ni expresar una decisión?" value={facts.voluntadAnulada} onChange={(value) => set("voluntadAnulada", value)} /></>}<ToggleQuestion legend="¿Utilizó la dependencia familiar, de cuidados o laboral para imponer el acto sexual?" value={facts.prevalimientoRelacion} onChange={(value) => set("prevalimientoRelacion", value)} /></>}</>}
    </>}
    {concept.id === "agresiones_lesiones" && <>
      <ToggleQuestion legend="¿Ha existido golpe o agresión física?" value={facts.agresionFisica} onChange={(value) => set("agresionFisica", value)} />
      {facts.agresionFisica && <><ToggleQuestion legend="¿Existe o se refiere alguna lesión?" value={facts.lesion} onChange={(value) => set("lesion", value)} />
        {facts.lesion && <ChoiceQuestion legend="¿Qué signos se observan o refiere la persona lesionada?" value={facts.signosLesion} options={injurySignsOptions} onChange={(value) => set("signosLesion", value as PublicSafetyFacts["signosLesion"])} />}
        {facts.resultadoAsistencial === "tratamiento_posterior" && <><ProtectedRelationshipQuestions facts={facts} set={set} /><ToggleQuestion legend="¿Se aumentó deliberadamente el sufrimiento o se atacó por sorpresa a una persona sin posibilidad de defensa?" value={facts.ensanamientoAlevosiaDocumentado} onChange={(value) => set("ensanamientoAlevosiaDocumentado", value)} /><ToggleQuestion legend="¿La víctima era menor de 14 años?" value={facts.victimaMenorCatorce} onChange={(value) => set("victimaMenorCatorce", value)} /><ToggleQuestion legend="¿La víctima necesita apoyo de otras personas para entender lo ocurrido o ejercer sus derechos por su discapacidad?" value={facts.discapacidadEspecialProteccion} onChange={(value) => set("discapacidadEspecialProteccion", value)} /></>}
        {facts.lesion && facts.signosLesion !== "perdida_traumatica" && <ChoiceQuestion legend="¿Qué asistencia ha recibido o le han indicado ya los sanitarios?" value={facts.resultadoAsistencial} options={medicalResultOptions} onChange={(value) => set("resultadoAsistencial", value as PublicSafetyFacts["resultadoAsistencial"])} />}
        {(facts.lesion === false || facts.resultadoAsistencial === "primera_asistencia") && <ProtectedRelationshipQuestions facts={facts} set={set} />}
        <ToggleQuestion legend="¿Se utilizó arma, botella, objeto o medio especialmente peligroso?" value={facts.medioPeligroso} onChange={(value) => set("medioPeligroso", value)} />
        {facts.medioPeligroso && <ToggleQuestion legend="¿Se documenta un peligro concreto para la vida o salud, además de la presencia del medio?" value={facts.peligroConcretoLesion} onChange={(value) => set("peligroConcretoLesion", value)} />}

        <ToggleQuestion legend="¿Hubo disparos, estrangulamiento, ataques reiterados a zonas vitales o expresiones de querer matar?" value={facts.indiciosFinalidadMatar} onChange={(value) => set("indiciosFinalidadMatar", value)} />
        {facts.indiciosFinalidadMatar && <div className="sp-question-help">Recoge zona corporal atacada, medio, número e intensidad de acciones, estrangulamiento o disparos, expresiones, conducta y motivo por el que cesó.</div>}
        <ToggleQuestion legend="¿La agresión se produjo en un contexto sexual?" value={facts.contextoSexual} onChange={(value) => set("contextoSexual", value)} />
      </>}
    </>}
    {concept.id === "agresiones_sexuales" && <>
      <ToggleQuestion legend="¿Se refiere un acto de contenido sexual no consentido?" value={facts.actoSexualNoConsentido} onChange={(value) => set("actoSexualNoConsentido", value)} />
      {facts.actoSexualNoConsentido && <><ToggleQuestion legend="¿La víctima es menor de 16 años?" value={facts.menorDieciseis} onChange={(value) => set("menorDieciseis", value)} />
        <ToggleQuestion legend="¿El presunto autor tiene 18 años o más?" value={facts.autorMayorEdad} onChange={(value) => { set("autorMayorEdad", value); setProcessFacts((current) => ({ ...current, autorMayorEdad: value })); }} />
        {facts.menorDieciseis && <><ChoiceQuestion legend="¿Qué conducta se refiere?" value={facts.conductaSexual} options={sexualConductOptions} onChange={(value) => set("conductaSexual", value as PublicSafetyFacts["conductaSexual"])} />{facts.conductaSexual === "hacer_presenciar" && <ToggleQuestion legend="¿La persona que sufrió los actos presenciados refiere que se realizaron contra su voluntad o mediante fuerza o amenazas?" value={facts.actosPresenciadosDelictivos} onChange={(value) => set("actosPresenciadosDelictivos", value)} />}{facts.conductaSexual === "contacto_tic" && <><ToggleQuestion legend="¿Consta propuesta de encuentro y actos materiales de acercamiento?" value={facts.propuestaEncuentroYAcercamiento} onChange={(value) => set("propuestaEncuentroYAcercamiento", value)} /><ToggleQuestion legend="¿Constan actos dirigidos a embaucar para obtener material o imágenes pornográficas?" value={facts.embaucarMaterialPornografico} onChange={(value) => set("embaucarMaterialPornografico", value)} /></>}</>}
        {(facts.conductaSexual === undefined || facts.conductaSexual === "acto_fisico") && <><ChoiceQuestion legend="¿Qué consta sobre el consentimiento?" value={facts.estadoConsentimiento} options={consentOptions} onChange={(value) => set("estadoConsentimiento", value as PublicSafetyFacts["estadoConsentimiento"])} />
          <ToggleQuestion legend="¿Hubo acceso carnal o introducción vaginal o anal de miembros corporales u objetos?" value={facts.penetracion} onChange={(value) => set("penetracion", value)} />
          <ToggleQuestion legend="¿Existió violencia o intimidación?" value={facts.violenciaIntimidacion} onChange={(value) => set("violenciaIntimidacion", value)} />
          <ToggleQuestion legend="¿La víctima estaba inconsciente o no podía reaccionar ni expresar una decisión?" value={facts.voluntadAnulada} onChange={(value) => set("voluntadAnulada", value)} />
          <ToggleQuestion legend="¿Intervinieron dos o más personas?" value={facts.variasPersonas} onChange={(value) => set("variasPersonas", value)} />
          <ToggleQuestion legend="¿Hubo violencia extrema o actos especialmente degradantes o vejatorios?" value={facts.violenciaExtremaDegradante} onChange={(value) => set("violenciaExtremaDegradante", value)} />
          <ToggleQuestion legend="¿Consta especial vulnerabilidad por edad, enfermedad, discapacidad u otra circunstancia?" value={facts.vulnerabilidadEspecial} onChange={(value) => set("vulnerabilidadEspecial", value)} />
          <ToggleQuestion legend="¿Se administraron fármacos, drogas u otra sustancia para anular la voluntad?" value={facts.sustanciasAdministradas} onChange={(value) => set("sustanciasAdministradas", value)} />
          {facts.menorDieciseis && <><ToggleQuestion legend="¿Se conocen varias personas coordinadas de forma estable para realizar estos hechos?" value={facts.organizacionCriminal} onChange={(value) => set("organizacionCriminal", value)} /><ToggleQuestion legend="¿Ambas personas refieren una relación aceptada por ellas y son de edades próximas?" value={facts.posibleExcepcion183Bis} onChange={(value) => set("posibleExcepcion183Bis", value)} /></>}
        </>}
        <ToggleQuestion legend="¿Se refiere pérdida de memoria, somnolencia, desorientación o posible administración de sustancias?" value={facts.posibleSumisionQuimica} onChange={(value) => set("posibleSumisionQuimica", value)} />
        {facts.posibleSumisionQuimica && <div className="sp-question-help">Pérdida de memoria, somnolencia intensa, desorientación, pérdida de conciencia no explicada, sospecha de sustancias o aprovechamiento de intoxicación.</div>}
        <ToggleQuestion legend="¿Existen lesiones?" value={facts.lesion} onChange={(value) => set("lesion", value)} />
        <ToggleQuestion legend="¿Existen amenazas o coacciones autónomas y adicionales?" value={facts.amenazasAutonomas} onChange={(value) => set("amenazasAutonomas", value)} />
        <ToggleQuestion legend="¿Hay arma u objeto peligroso?" value={facts.medioPeligroso} onChange={(value) => set("medioPeligroso", value)} />
        <ProtectedRelationshipQuestions facts={facts} set={set} askVictimSex askSuperiority />
        <ToggleQuestion legend="¿Utilizó la dependencia familiar, de cuidados o laboral para imponer el acto sexual?" value={facts.prevalimientoRelacion} onChange={(value) => set("prevalimientoRelacion", value)} />
      </>}
    </>}
    {concept.id === "peleas_rinas" && <>
      <ChoiceQuestion legend="¿Cómo se desarrolla el enfrentamiento?" value={facts.tipoRina} options={fightTypeOptions} onChange={(value) => set("tipoRina", value as PublicSafetyFacts["tipoRina"])} />
      {facts.tipoRina && <><ToggleQuestion legend="¿Se utilizan botellas, cuchillos, palos u otros instrumentos peligrosos?" value={facts.medioPeligroso} onChange={(value) => set("medioPeligroso", value)} />
        <ToggleQuestion legend="¿Hay personas lesionadas?" value={facts.lesion} onChange={(value) => set("lesion", value)} />
        {facts.lesion && <ToggleQuestion legend="¿Puede identificarse quién causó una lesión concreta?" value={facts.lesionIndividualizable} onChange={(value) => set("lesionIndividualizable", value)} />}
        <ToggleQuestion legend="¿La víctima es agente?" value={facts.victimaAgente} onChange={(value) => set("victimaAgente", value)} />
      </>}
    </>}
    {concept.id === "amenazas_coacciones" && <>
      <ChoiceQuestion legend="¿Qué está haciendo la persona?" value={facts.conductaLibertad} options={freedomConductOptions} onChange={(value) => set("conductaLibertad", value as PublicSafetyFacts["conductaLibertad"])} />
      {facts.conductaLibertad === "amenaza" && <><ChoiceQuestion legend="¿Qué mal anuncia?" value={facts.malAnunciado} options={threatHarmOptions} onChange={(value) => set("malAnunciado", value as PublicSafetyFacts["malAnunciado"])} />
        <ToggleQuestion legend="¿Exige algo o impone alguna condición?" value={facts.condicionImpuesta} onChange={(value) => set("condicionImpuesta", value)} />
        {facts.malAnunciado === "entidad_delictiva" && facts.condicionImpuesta && <ToggleQuestion legend="¿Se consiguió el propósito de la condición?" value={facts.propositoConseguido} onChange={(value) => set("propositoConseguido", value)} />}
        {facts.malAnunciado === "no_delictivo" && facts.condicionImpuesta && <><ToggleQuestion legend="¿Exigía cumplir una obligación que consta en documento o reconoce la persona afectada?" value={facts.condicionConductaDebida} onChange={(value) => set("condicionConductaDebida", value)} /><ToggleQuestion legend="¿Se consiguió el propósito de la condición?" value={facts.propositoConseguido} onChange={(value) => set("propositoConseguido", value)} /></>}
        {facts.malAnunciado === "menor_entidad" && <ProtectedRelationshipQuestions facts={facts} set={set} />}
      </>}
      {facts.conductaLibertad === "coaccion" && <><ChoiceQuestion legend="¿Cómo impone o impide la conducta?" value={facts.coaccionEntidad} options={coactionOptions} onChange={(value) => set("coaccionEntidad", value as PublicSafetyFacts["coaccionEntidad"])} />{facts.coaccionEntidad === "leve" && <ProtectedRelationshipQuestions facts={facts} set={set} />}</>}
      {facts.conductaLibertad === "acoso" && <><ChoiceQuestion legend="¿Qué conducta reiterada se documenta?" value={facts.conductaAcoso} options={harassmentOptions} onChange={(value) => set("conductaAcoso", value as PublicSafetyFacts["conductaAcoso"])} /><ToggleQuestion legend="¿La conducta fue insistente y reiterada sin autorización?" value={facts.acosoReiterado} onChange={(value) => set("acosoReiterado", value)} /><ToggleQuestion legend="¿Alteró el desarrollo normal de la vida cotidiana?" value={facts.alteracionVidaCotidiana} onChange={(value) => set("alteracionVidaCotidiana", value)} /><ToggleQuestion legend="¿Consta edad, enfermedad o circunstancia que le dificulta protegerse?" value={facts.vulnerabilidadEspecial} onChange={(value) => set("vulnerabilidadEspecial", value)} /><ProtectedRelationshipQuestions facts={facts} set={set} /></>}
      {facts.conductaLibertad && facts.conductaLibertad !== "acoso" && <><ToggleQuestion legend="¿Utiliza o exhibe arma u objeto peligroso?" value={facts.medioPeligroso} onChange={(value) => set("medioPeligroso", value)} />
        <ToggleQuestion legend="¿Hay mensajes, audios, llamadas u otros soportes?" value={facts.soportes} onChange={(value) => set("soportes", value)} />
      </>}
    </>}
    {showComplaintQuestion && <><ChoiceQuestion legend="¿Quién ha comunicado los hechos para denunciarlos?" value={facts.procedibilidadSexual} options={procedureOptions} onChange={(value) => { set("procedibilidadSexual", value as PublicSafetyFacts["procedibilidadSexual"]); set("noDeseaDenunciar", value === "pendiente"); setProcessFacts((current) => ({ ...current, denunciaOQuerella: value !== "pendiente" })); }} />
      <div className="sp-question-help">La denuncia puede ser oral y documentarse después. Si está pendiente, continúan protección, asistencia, diligencias urgentes, preservación de indicios y coordinación.</div>
    </>}
    {needsProcessualFacts && <ProcessualControls flagrante={flagrante} setFlagrante={setFlagrante} facts={processFacts} setFacts={setProcessFacts} minor={fixedMinorOffence} complaintRequired={complaintRequired} complaintManagedExternally={showComplaintQuestion} ageManagedExternally={concept.id === "agresiones_sexuales"} />}
    <IncidentResolvedOutcome result={result} onNavigate={onNavigate} showProcessual />
  </>;
}

function ProtectedRelationshipQuestions({ facts, set, askVictimSex = false, askSuperiority = false }: { facts: PublicSafetyFacts; set: <K extends keyof PublicSafetyFacts>(key: K, value: PublicSafetyFacts[K]) => void; askVictimSex?: boolean; askSuperiority?: boolean }) {
  const setPartner = (value: RelationalAnswer) => {
    set("parejaExpareja", value);
    set("relacionFamiliar", undefined);
    set("convivencia", undefined);
    if (value !== "si") {
      set("sexoAutor", undefined);
      if (!askVictimSex) set("sexoVictima", undefined);
    }
  };
  const setFamily = (value: RelationalAnswer) => {
    set("relacionFamiliar", value);
    set("convivencia", undefined);
  };
  return <>
    {askVictimSex && <ChoiceQuestion legend="Sexo de la víctima a efectos de competencia" value={facts.sexoVictima} options={sexOptions} onChange={(value) => set("sexoVictima", value as PublicSafetyFacts["sexoVictima"])} />}
    <TriStateQuestion legend="¿Existe o existió relación de pareja o análoga de afectividad?" value={facts.parejaExpareja} onChange={setPartner} />
    {facts.parejaExpareja === "si" && <><ChoiceQuestion legend="Sexo del presunto autor a efectos del ámbito VioGén" value={facts.sexoAutor} options={sexOptions} onChange={(value) => set("sexoAutor", value as PublicSafetyFacts["sexoAutor"])} />{!askVictimSex && <ChoiceQuestion legend="Sexo de la víctima a efectos del ámbito VioGén" value={facts.sexoVictima} options={sexOptions} onChange={(value) => set("sexoVictima", value as PublicSafetyFacts["sexoVictima"])} />}</>}
    {facts.parejaExpareja === "no" && <TriStateQuestion legend="¿Existe relación familiar entre autor y víctima?" value={facts.relacionFamiliar} onChange={setFamily} />}
    {facts.parejaExpareja === "no" && facts.relacionFamiliar === "no" && <TriStateQuestion legend="¿Forman parte del mismo núcleo de convivencia?" value={facts.convivencia} onChange={(value) => set("convivencia", value)} />}
    {askSuperiority && <TriStateQuestion legend="¿Se aprovechó una dependencia laboral, profesional o de cuidados para imponer la conducta?" value={facts.abusoSuperioridad} onChange={(value) => set("abusoSuperioridad", value)} />}
  </>;
}

function ChoiceQuestion({ legend, value, options, onChange }: { legend: string; value: string | undefined; options: Array<[string, string]>; onChange: (value: string) => void }) { return <fieldset className="sp-choice"><legend>{legend}</legend>{options.map(([id, label]) => <label key={id}><input type="radio" checked={value === id} onChange={() => onChange(id)} /> {label}</label>)}</fieldset>; }
function ToggleQuestion({ legend, value, onChange }: { legend: string; value: boolean | undefined; onChange: (value: boolean | undefined) => void }) { return <fieldset className="sp-choice"><legend>{legend}</legend><label><input type="radio" checked={value === true} onChange={() => onChange(true)} /> Sí</label><label><input type="radio" checked={value === false} onChange={() => onChange(false)} /> No</label><label><input type="radio" checked={value === undefined} onChange={() => onChange(undefined)} /> No se conoce todavía</label></fieldset>; }
function TriStateQuestion({ legend, value, onChange }: { legend: string; value: RelationalAnswer | undefined; onChange: (value: RelationalAnswer) => void }) { return <fieldset className="sp-choice"><legend>{legend}</legend>{relationalAnswerOptions.map(([id, label]) => <label key={id}><input type="radio" checked={value === id} onChange={() => onChange(id as RelationalAnswer)} /> {label}</label>)}</fieldset>; }

export function IncidentResolvedOutcome({ result, onNavigate, showProcessual }: { result: PublicSafetyOutcome; onNavigate: (id: string) => void; showProcessual: boolean }) {
  const attentions = result.resultados.filter(isIncidentAttention);
  const outcomes = result.resultados.filter((item) => !isIncidentAttention(item));
  const actions = uniqueItems(outcomes.flatMap((item) => item.actuacion).filter((item) => !isContinuationAction(item) && !isAttentionAction(item)));
  const attentionItems = uniqueItems([...attentions.map((item) => `${item.titulo}: ${item.texto}`), ...outcomes.flatMap((item) => item.actuacion).filter(isAttentionAction)]);
  const attentionReferences = attentions.flatMap((item) => item.referenciasProcesales ?? []).filter((item, index, all) => all.findIndex((candidate) => candidate.id === item.id) === index);
  return <>{outcomes.map((item, index) => <div key={`${item.titulo}-${index}`} className={item.destacado ? `sp-incident-${item.destacado}` : undefined}><ResultCard title={item.titulo} norma={item.norma} clasificacion={item.clasificacion} text={item.texto} showText referenciasProcesales={item.referenciasProcesales} /></div>)}
    {result.procedibilidad && <section className={`sp-section sp-procedure ${result.procedibilidad.estado.startsWith("PENDIENTE") ? "pending" : "complete"}`}><h3>PROCEDIBILIDAD</h3><strong>{result.procedibilidad.estado}</strong><p>{result.procedibilidad.fundamento}</p></section>}
    {result.procesal && showProcessual ? <><AuthorSituation decision={result.procesal} explain={false} /><Continuation decision={result.procesal} additionalItems={actions} /><ProcessualExplanation decision={result.procesal} /></> : <OperationalSection title="Actuación inmediata" items={actions} />}
    <OperationalSection title="Atención" items={attentionItems} />
    {attentionReferences.length > 0 && <section className="sp-section sp-attention-legal-help"><h3>REFERENCIAS PROCESALES</h3><ContextualProcessualHelp usos={attentionReferences} /></section>}
    {result.conexiones.length > 0 && <section className="sp-section"><h3>Conexiones activas</h3><div className="sp-connections">{result.conexiones.map((item) => item.conceptId ? <button key={`${item.conceptId}-${item.etiqueta}`} onClick={() => onNavigate(item.conceptId)}><span className="sp-connection-icon" aria-hidden="true">{publicSecurityConceptIcon(item.conceptId)}</span><span><strong>{item.etiqueta}</strong><small>{item.motivo}</small></span><b aria-hidden="true">›</b></button> : <div key={item.etiqueta}><strong>{item.etiqueta}</strong><small>{item.motivo}</small></div>)}</div></section>}
    {outcomes.map((item, index) => <PendingDetails key={index} text={item.incertidumbre} />)}
    {outcomes.filter((item) => item.supuestoPenalId).map((item, index) => <ExportPenaltyFramework key={index} supuestoPenalId={item.supuestoPenalId!} />)}
    <LegalFoundation normas={uniqueItems(result.resultados.map((item) => item.norma))} />
  </>;
}

function WeaponDecision({ concept, facts }: { concept: PublicConcept; facts: PublicSafetyFacts }) {
  const ordinaryObject = concept.id === "objetos_peligrosos";
  const [tipo, setTipo] = useState<WeaponObjectInput["tipo"]>("navaja");
  const [mecanismo, setMecanismo] = useState<"automatico" | "no_automatico" | "dudoso">("dudoso");
  const [longitudNavaja, setLongitudNavaja] = useState<"supera_11" | "no_supera_11" | "dudosa">("dudosa");
  const [menorOnce, setMenorOnce] = useState(false); const [dosFilos, setDosFilos] = useState(false); const [puntiaguda, setPuntiaguda] = useState(false);
  const [armamento, setArmamento] = useState<"aprobado" | "imitacion" | "no" | "dudoso">("dudoso");
  const [circunstanciaTenencia, setCircunstanciaTenencia] = useState<"ninguna" | "contemplacion" | "reparacion" | "transmision">("ninguna");
  const [disponibilidad, setDisponibilidad] = useState<"encima" | "efectos" | "accesible" | "vehiculo" | "sin_disponente">("efectos"); const [comportamiento, setComportamiento] = useState<WeaponConduct>(facts.medioPeligroso ? "usa" : "porte"); const [contexto, setContexto] = useState<"sin_incidente" | "altercado" | "violento" | "amenazas" | "otro_delito" | "otras">("sin_incidente"); const [flagrante, setFlagrante] = useState<boolean>(); const [processFacts, setProcessFacts] = useState<ProcessualFactsForm>({});
  const [motivo, setMotivo] = useState<WeaponContextInput["motivo"]>();
  const [transporte, setTransporte] = useState<WeaponContextInput["transporte"]>();
  const [lugar, setLugar] = useState<WeaponContextInput["lugar"]>();
  const [momento, setMomento] = useState<WeaponContextInput["momento"]>();
  const [consumo, setConsumo] = useState<WeaponContextInput["consumo"]>();
  const [accesoRestringido, setAccesoRestringido] = useState<WeaponContextInput["accesoRestringido"]>();
  const [motivoSeguridadFinalizado, setMotivoSeguridadFinalizado] = useState<WeaponContextInput["motivoSeguridadFinalizado"]>();
  const processual = processualInput(flagrante, processFacts);
  const processualAnswered = hasProcessualAnswer(flagrante, processFacts);
  const clearCarry = () => { setCircunstanciaTenencia("ninguna"); setMotivo(undefined); setTransporte(undefined); setLugar(undefined); setMomento(undefined); setConsumo(undefined); setAccesoRestringido(undefined); setMotivoSeguridadFinalizado(undefined); };
  const chooseBehaviour = (value: WeaponConduct) => { setComportamiento(value); if (value !== "porte") clearCarry(); if (value === "exhibe" && contexto === "sin_incidente") setContexto("altercado"); };
  const chooseTipo = (value: WeaponObjectInput["tipo"]) => { setTipo(value); setMecanismo("dudoso"); setLongitudNavaja("dudosa"); setMenorOnce(false); setDosFilos(false); setPuntiaguda(false); setArmamento("dudoso"); clearCarry(); };
  const chooseMechanism = (value: typeof mecanismo) => { setMecanismo(value); setLongitudNavaja("dudosa"); if (value === "automatico") clearCarry(); };
  const choosePlace = (value: NonNullable<WeaponContextInput["lugar"]>) => { setLugar(value); if (!["establecimiento", "ocio", "reunion"].includes(value)) { setMomento(undefined); setConsumo(undefined); } setAccesoRestringido(undefined); setMotivoSeguridadFinalizado(undefined); };
  const showAvailability = ordinaryObject && comportamiento === "porte";
  const showContext = comportamiento === "manipula" || comportamiento === "exhibe";
  const showTenenciaExcepcional = !ordinaryObject && comportamiento === "porte";
  const prohibitedTechnical = mecanismo === "automatico" && tipo === "navaja" || tipo === "hoja" && menorOnce && dosFilos && puntiaguda;
  const showCarry = !ordinaryObject && comportamiento === "porte" && !prohibitedTechnical;
  const sensitivePlace = lugar === "establecimiento" || lugar === "ocio" || lugar === "reunion";
  const legitimatePurpose = motivo === "trabajo" || motivo === "actividad" || motivo === "trayecto";
  const protectedTransport = transporte === "funda" || transporte === "equipamiento";
  const coherentPlace = lugar === "trayecto" || motivo === "trabajo" && lugar === "trabajo" || motivo === "actividad" && lugar === "actividad";
  const showSafetyAccess = showCarry && legitimatePurpose && protectedTransport && coherentPlace && consumo !== "si";
  const contextOptions = comportamiento === "exhibe" ? weaponRelatedContext : weaponContext;
  const inferredAvailability = ordinaryObject ? disponibilidad : transporte === "bolsillo" || transporte === "accesible" ? "accesible" : "efectos";
  const result = { ...resolveWeaponOutcome({ tipo: ordinaryObject ? "objeto" : tipo, mecanismo, longitudNavaja, hojaMenorOnce: menorOnce, dosFilos, puntiaguda, armamento, supuestoEspecifico: circunstanciaTenencia !== "ninguna", circunstanciaTenencia: circunstanciaTenencia === "ninguna" ? undefined : circunstanciaTenencia }, { disponibilidad: inferredAvailability, comportamiento, contexto: showContext ? contexto : undefined, motivo, transporte, lugar, momento, consumo, accesoRestringido: showSafetyAccess ? accesoRestringido : undefined, motivoSeguridadFinalizado: showSafetyAccess && accesoRestringido === "si" ? motivoSeguridadFinalizado : undefined, ...processual }), processualAnswered };
  return <>{facts.medioPeligroso && <div className="sp-highlight neutral"><strong>MEDIO PELIGROSO YA REGISTRADO</strong><p>Se conserva como hecho de la intervención. Completa solo las características del objeto necesarias para su descripción.</p></div>}<OperationalSection title="Qué comprobar" items={concept.comprobar} />{facts.medioPeligroso ? <div className="sp-question-help">La conducta contra una persona ya consta en la intervención; completa únicamente la identificación del objeto.</div> : <fieldset className="sp-choice"><legend>¿Qué ocurre con el objeto?</legend>{weaponBehaviour.map(([id, label]) => <label key={id}><input type="radio" checked={comportamiento === id} onChange={() => chooseBehaviour(id as WeaponConduct)} /> {label}</label>)}</fieldset>}{showAvailability && <fieldset className="sp-choice"><legend>¿Dónde se encuentra?</legend>{weaponAvailability.map(([id, label]) => <label key={id}><input type="radio" checked={disponibilidad === id} onChange={() => setDisponibilidad(id as typeof disponibilidad)} /> {label}</label>)}</fieldset>}{showContext && <fieldset className="sp-choice"><legend>¿Qué situación se observa?</legend>{contextOptions.map(([id, label]) => <label key={id}><input type="radio" checked={contexto === id} onChange={() => setContexto(id as typeof contexto)} /> {label}</label>)}</fieldset>}{ordinaryObject ? <div className="sp-highlight neutral"><strong>OBJETO ORDINARIO</strong><ul><li>Solo porte: no implica infracción automática.</li><li>Intimidación o agresión: analizar primero vía penal.</li><li>El uso puede ser relevante aunque el objeto no sea arma.</li></ul></div> : <><fieldset className="sp-choice"><legend>¿Qué tipo de arma blanca se observa?</legend>{bladeTypes.map(([id, label]) => <label key={id}><input type="radio" checked={tipo === id} onChange={() => chooseTipo(id as WeaponObjectInput["tipo"])} /> {label}</label>)}</fieldset>{tipo === "navaja" && <fieldset className="sp-choice"><legend>¿Cómo es el mecanismo de apertura?</legend><p className="sp-question-help">Indica si el mecanismo es automático.</p>{mechanismOptions.map(([id, label]) => <label key={id}><input type="radio" checked={mecanismo === id} onChange={() => chooseMechanism(id as typeof mecanismo)} /> {label}</label>)}{mecanismo === "no_automatico" && <div className="sp-nested-question"><strong>Longitud desde el reborde o tope del mango hasta el extremo</strong>{manualLengthOptions.map(([id, label]) => <label key={id}><input type="radio" checked={longitudNavaja === id} onChange={() => setLongitudNavaja(id as typeof longitudNavaja)} /> {label}</label>)}</div>}</fieldset>}{tipo === "hoja" && <fieldset className="sp-choice"><legend>¿Reúne las tres características de un puñal?</legend><label><input type="checkbox" checked={menorOnce} onChange={(event) => setMenorOnce(event.target.checked)} /> Hoja menor de 11 cm</label><label><input type="checkbox" checked={dosFilos} onChange={(event) => setDosFilos(event.target.checked)} /> Dos filos</label><label><input type="checkbox" checked={puntiaguda} onChange={(event) => setPuntiaguda(event.target.checked)} /> Punta</label></fieldset>}{(tipo === "cuchillo" || tipo === "machete") && <fieldset className="sp-choice"><legend>¿Forma parte de un armamento debidamente aprobado?</legend>{armamentOptions.map(([id, label]) => <label key={id}><input type="radio" checked={armamento === id} onChange={() => setArmamento(id as typeof armamento)} /> {label}</label>)}</fieldset>}{showTenenciaExcepcional && <fieldset className="sp-choice"><legend>¿Existe una circunstancia excepcional de tenencia?</legend>{exceptionalTenureOptions.map(([id, label]) => <label key={id}><input type="radio" checked={circunstanciaTenencia === id} onChange={() => setCircunstanciaTenencia(id as typeof circunstanciaTenencia)} /> {label}</label>)}</fieldset>}{showCarry && <><fieldset className="sp-choice"><legend>¿Para qué lleva el objeto?</legend>{carryPurposeOptions.map(([id, label]) => <label key={id}><input type="radio" checked={motivo === id} onChange={() => { setMotivo(id as NonNullable<typeof motivo>); setAccesoRestringido(undefined); setMotivoSeguridadFinalizado(undefined); }} /> {label}</label>)}</fieldset><fieldset className="sp-choice"><legend>¿Cómo lo transporta?</legend>{carryTransportOptions.map(([id, label]) => <label key={id}><input type="radio" checked={transporte === id} onChange={() => { setTransporte(id as NonNullable<typeof transporte>); setAccesoRestringido(undefined); setMotivoSeguridadFinalizado(undefined); }} /> {label}</label>)}</fieldset><fieldset className="sp-choice"><legend>¿Dónde se encuentra?</legend>{carryPlaceOptions.map(([id, label]) => <label key={id}><input type="radio" checked={lugar === id} onChange={() => choosePlace(id as NonNullable<typeof lugar>)} /> {label}</label>)}</fieldset>{sensitivePlace && <fieldset className="sp-choice"><legend>Datos adicionales relevantes</legend>{momentOptions.map(([id, label]) => <label key={id}><input type="radio" checked={momento === id} onChange={() => setMomento(id as NonNullable<typeof momento>)} /> {label}</label>)}<span className="sp-choice-divider">¿Se observan signos de consumo o influencia?</span>{yesNoUnknown.map(([id, label]) => <label key={`consumo-${id}`}><input type="radio" checked={consumo === id} onChange={() => setConsumo(id as NonNullable<typeof consumo>)} /> {label}</label>)}</fieldset>}{showSafetyAccess && <fieldset className="sp-choice"><legend>¿Intenta acceder a un espacio con una restricción concreta de seguridad?</legend>{yesNoUnknown.map(([id, label]) => <label key={`acceso-${id}`}><input type="radio" checked={accesoRestringido === id} onChange={() => { setAccesoRestringido(id as NonNullable<typeof accesoRestringido>); if (id !== "si") setMotivoSeguridadFinalizado(undefined); }} /> {label}</label>)}{accesoRestringido === "si" && <div className="sp-nested-question"><strong>¿Ha desaparecido el motivo concreto de seguridad?</strong>{yesNoUnknown.map(([id, label]) => <label key={`fin-${id}`}><input type="radio" checked={motivoSeguridadFinalizado === id} onChange={() => setMotivoSeguridadFinalizado(id as NonNullable<typeof motivoSeguridadFinalizado>)} /> {label}</label>)}</div>}</fieldset>}</>}</>}<div className="sp-dimensions"><p><span>CLASIFICACIÓN DEL OBJETO</span><strong>{result.clasificacionObjeto}</strong></p><p><span>CONDUCTA OBSERVADA</span><strong>{result.conducta}</strong></p></div>{result.kind === "penal" && <ProcessualControls flagrante={flagrante} setFlagrante={setFlagrante} facts={processFacts} setFacts={setProcessFacts} />}<ResolvedOutcome result={result} weapon={ordinaryObject ? "object" : "weapon"} showFoundation={false} /><WeaponDetails concept={concept} result={result} ordinaryObject={ordinaryObject} /></>;
}

function WeaponDetails({ concept, result, ordinaryObject }: { concept: PublicConcept; result: WeaponOutcome; ordinaryObject: boolean }) { return <div className="sp-common">{result.salidaSubsidiaria && <CollapsibleSection title="Salida administrativa subsidiaria"><p>{result.salidaSubsidiaria}</p></CollapsibleSection>}{result.derivaOtroDelito && <CollapsibleSection title={ordinaryObject ? "Posible delito cometido utilizando el objeto" : "Delito cometido utilizando el arma"}><p>{ordinaryObject ? "La clasificación del objeto no elimina su relevancia por el uso ni activa automáticamente el art. 563 CP." : "La vía del art. 563 y el delito cometido utilizando el arma exigen sus propios requisitos."}</p>{result.dependenciaFutura && <p><strong>{result.dependenciaFutura}</strong></p>}</CollapsibleSection>}<CollapsibleSection title="Datos para acta o diligencias"><Checklist items={["Tipo, características y dimensiones relevantes.", "Lugar, motivo y forma de porte.", "Actividad relacionada y accesibilidad.", "Conducta y contexto observados.", "Fotografías, cuando proceda."]} /></CollapsibleSection><CollapsibleSection title="Fundamento jurídico">{concept.detalle?.length ? <Checklist items={concept.detalle} /> : null}{!ordinaryObject && <p>El art. 563 exige conjuntamente los requisitos constitucionales aplicables a este supuesto.</p>}<Checklist items={concept.fuentes ?? []} /></CollapsibleSection></div> }

function AuthorityDecision({ concept }: { concept: PublicConcept }) {
  const [selectionFacts, setSelectionFacts] = useState<AuthorityFacts>({});
  const [flagrante, setFlagrante] = useState<boolean>();
  const [processFacts, setProcessFacts] = useState<ProcessualFactsForm>({});
  const set = <K extends keyof AuthorityFacts>(key: K, value: AuthorityFacts[K]) => setSelectionFacts((current) => ({ ...current, [key]: value }));
  const result = resolveAuthorityFromFacts(concept.id, { ...selectionFacts, ...processualInput(flagrante, processFacts) });
  const minor = result?.clasificacion === "DELITO LEVE";
  const complaintRequired = result?.procedibilidadPenal === "denuncia" || result?.procedibilidadPenal === "sexual_191";
  return <>
    <ChoiceQuestion legend="¿Qué hizo concretamente la persona?" value={selectionFacts.conductaObservada} options={authorityConductOptions} onChange={(value) => { setSelectionFacts({ conductaObservada: value as AuthorityFacts["conductaObservada"] }); setFlagrante(undefined); setProcessFacts({}); }} />
    {selectionFacts.conductaObservada && <ToggleQuestion legend="¿La actuación se dirigió contra la persona mientras prestaba su servicio o por ese servicio?" value={selectionFacts.enFunciones} onChange={(value) => set("enFunciones", value)} />}
    {selectionFacts.conductaObservada === "negativa" && <>
      <ToggleQuestion legend="¿Se comunicó una orden concreta dentro de las funciones del agente, que la persona entendió y podía cumplir?" value={selectionFacts.ordenConcretaComprendida} onChange={(value) => set("ordenConcretaComprendida", value)} />
      {selectionFacts.ordenConcretaComprendida && <><ToggleQuestion legend="¿Persistió deliberadamente en negarse tras reiterar la orden?" value={selectionFacts.negativaPersistente} onChange={(value) => set("negativaPersistente", value)} /><ToggleQuestion legend="¿La negativa impidió la actuación o mantuvo un peligro concreto para personas o bienes?" value={selectionFacts.servicioImpedido} onChange={(value) => set("servicioImpedido", value)} /></>}
    </>}
    {selectionFacts.conductaObservada === "ataque" && <>
      <ChoiceQuestion legend="¿Qué función desempeña la persona atacada?" value={selectionFacts.victimaAtentado} options={attackedVictimOptions} onChange={(value) => set("victimaAtentado", value as AuthorityFacts["victimaAtentado"])} />
      {selectionFacts.victimaAtentado && <>
        <ToggleQuestion legend="¿Se usó un arma u objeto contra la persona?" value={selectionFacts.armaUsada551} onChange={(value) => set("armaUsada551", value)} />
        <ToggleQuestion legend="¿Hubo estrangulamiento, golpes a zonas vitales, lanzamiento de objetos contundentes u otra violencia que pudiera causar lesiones importantes?" value={selectionFacts.violenciaPeligrosa551} onChange={(value) => set("violenciaPeligrosa551", value)} />
        <ToggleQuestion legend="¿Se dirigió un vehículo de motor contra la persona?" value={selectionFacts.vehiculoMotor551} onChange={(value) => set("vehiculoMotor551", value)} />
        <ToggleQuestion legend="¿Ocurrió en un motín o incidente colectivo dentro de un centro penitenciario?" value={selectionFacts.incidentePenitenciario551} onChange={(value) => set("incidentePenitenciario551", value)} />
      </>}
    </>}
    {selectionFacts.conductaObservada === "amenaza_concreta" && <>
      <ToggleQuestion legend="¿La amenaza estaba condicionada a que la víctima hiciera u omitiera algo?" value={selectionFacts.condicionAmenaza} onChange={(value) => set("condicionAmenaza", value)} />
      {selectionFacts.condicionAmenaza && <ToggleQuestion legend="¿Se consiguió lo que exigía?" value={selectionFacts.propositoConseguido} onChange={(value) => set("propositoConseguido", value)} />}
    </>}
    {result?.supuestoPenalId && <ProcessualControls flagrante={flagrante} setFlagrante={setFlagrante} facts={processFacts} setFacts={setProcessFacts} minor={minor} complaintRequired={complaintRequired} />}
    {result ? <ResolvedOutcome result={result} showProcessual /> : <>
      <OperationalSection title="Actuación inmediata" items={["Proteger a las personas y hacer cesar las agresiones.", "Identificar a las personas, recoger expresiones y secuencia de hechos, testigos y cámaras.", "Comprobar la función de la persona afectada y la relación del hecho con su servicio antes de atribuir un delito contra ella."]} /><LegalFoundation normas={[concept.norma]} detalle="La función desempeñada, la relación con el servicio y la conducta concreta deben comprobarse antes de atribuir el hecho." />
    </>}
  </>;
}
const authorityConductOptions: Array<[string, string]> = [["insulto", "Insulta o expresa desprecio sin anunciar un daño"], ["negativa", "Se niega a cumplir una orden"], ["oposicion", "Se aparta, se queda inmóvil o dificulta brevemente la actuación"], ["forcejeo", "Forcejea o mantiene oposición física para impedir la actuación, sin atacar"], ["ataque", "Golpea, intenta golpear o inicia un ataque inmediato"], ["amenaza_concreta", "Anuncia matar, lesionar, forzar actos sexuales, privar de libertad o destruir bienes"], ["expresion_intimidatoria", "Pronuncia una expresión intimidatoria aislada sin concretar esos daños"]];

function PatrimonyDecision({ facts, onNavigate }: { facts: PublicSafetyFacts; onNavigate: (id: string) => void }) {
  const [patrimony, setPatrimony] = useState<PatrimonyFacts>({});
  const [flagrante, setFlagrante] = useState<boolean>();
  const [processFacts, setProcessFacts] = useState<ProcessualFactsForm>({});
  const set = <K extends keyof PatrimonyFacts>(key: K, value: PatrimonyFacts[K]) => setPatrimony((current) => {
    const next = { ...current, [key]: value };
    if (key === "posesionPrevia") {
      next.recepcionLegitima = value === "autor_entrega_legitima";
      next.obligacionDevolverEntregar = undefined;
      next.facultadesAdministracion = undefined;
      next.excesoFacultadesConPerjuicio = undefined;
      next.conductaApropiacionONegacion = undefined;
      next.viaApropiacionFuera253 = undefined;
    }
    if (key === "tipoLugar") next.especialGravedad2414 = undefined;
    if (key === "violenciaFisica" || key === "intimidacion") {
      next.momentoViolencia = undefined;
      next.conexionViolenciaApoderamiento = undefined;
      next.armaPresente = undefined;
      next.armaUsada = undefined;
      next.lesionAutonoma = undefined;
      next.amenazaCoaccionAutonoma = undefined;
    }
    return next;
  });
  const outcome = resolvePatrimonyOutcome({ ...patrimony, vinculoFamiliar268: patrimony.relacionArt268 === "familiar" ? patrimony.vinculoFamiliar268 : undefined }, processualInput(flagrante, processFacts), facts);
  const minor = outcome.gravedad === "DELITO LEVE";
  const complaintRequired = outcome.procedibilidadPenal === "denuncia" || outcome.procedibilidadPenal === "sexual_191";
  const mainOptions: Array<[NonNullable<PatrimonyFacts["hechoPrincipal"]>, string]> = [["apoderamiento", "Se llevan o intentan llevar una cosa"], ["recepcion", "La cosa se recibió legítimamente y después no se devuelve o se dispone de ella"], ["danos", "Se daña o destruye una cosa"], ["no_claro", "No puede determinarse todavía"]];
  const eventChange = (value: NonNullable<PatrimonyFacts["hechoPrincipal"]>) => { setPatrimony({ hechoPrincipal: value }); setFlagrante(undefined); setProcessFacts({}); };
  const yesNo = (legend: string, key: keyof PatrimonyFacts) => <ToggleQuestion legend={legend} value={patrimony[key] as boolean | undefined} onChange={(value) => set(key, value as never)} />;
  return <>
    <fieldset className="sp-choice"><legend>¿Cuál es el hecho principal observado?</legend>{mainOptions.map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.hechoPrincipal === value} onChange={() => eventChange(value)} /> {label}</label>)}</fieldset>
    {patrimony.hechoPrincipal && patrimony.hechoPrincipal !== "no_claro" && <>
      <ChoiceQuestion legend="¿Qué relación existe entre las personas implicadas?" value={patrimony.relacionArt268} options={patrimonyRelationshipOptions} onChange={(value) => set("relacionArt268", value as PatrimonyFacts["relacionArt268"])} />
      {patrimony.relacionArt268 === "conyuge" && <>{yesNo("¿Existe separación legal o de hecho?", "separacionConyugal")}{patrimony.separacionConyugal === false && yesNo("¿Existe proceso judicial de separación, divorcio o nulidad?", "procesoSeparacionDivorcioNulidad")}</>}
      {patrimony.relacionArt268 === "familiar" && <><fieldset className="sp-choice"><legend>Parentesco concreto</legend>{[["ascendiente", "Ascendiente"], ["descendiente", "Descendiente"], ["hermano", "Hermano/a"], ["afin_primer_grado", "Suegro/a, yerno o nuera"], ["otro", "Otro vínculo"], ["no_determinado", "No determinado"]].map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.vinculoFamiliar268 === value} onChange={() => set("vinculoFamiliar268", value as PatrimonyFacts["vinculoFamiliar268"])} /> {label}</label>)}</fieldset>{patrimony.vinculoFamiliar268 === "afin_primer_grado" && yesNo("¿Conviven?", "afinPrimerGradoConvive")}</>}
      {["conyuge", "familiar"].includes(patrimony.relacionArt268 ?? "") && <>{yesNo("¿Se aprovechó que la víctima no podía proteger sus bienes por su edad o discapacidad?", "abusoVulnerabilidadEdadDiscapacidad")}{yesNo("¿Participa un tercero extraño?", "terceroExtranoParticipa")}</>}
      <fieldset className="sp-choice"><legend>Titularidad de la cosa</legend>{[["ajena", "Ajena"], ["propia", "Propia"], ["compartida", "Compartida"], ["no_determinada", "No determinada"]].map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.titularidad === value} onChange={() => set("titularidad", value as PatrimonyFacts["titularidad"])} /> {label}</label>)}</fieldset>
    </>}
    {patrimony.hechoPrincipal === "apoderamiento" && patrimony.titularidad === "ajena" && <>
      {yesNo("¿Se lleva, oculta, vende o utiliza para sí una cosa de otra persona?", "intencionApropiacionBeneficio")}
      {patrimony.intencionApropiacionBeneficio === true && <ToggleQuestion legend="¿El titular manifiesta que autorizó llevarse o utilizar la cosa?" value={invertBooleanAnswer(patrimony.sinConsentimiento)} onChange={(value) => set("sinConsentimiento", invertBooleanAnswer(value))} />}
      {patrimony.sinConsentimiento === true && <ToggleQuestion legend="¿Hay violencia física?" value={patrimony.violenciaFisica} onChange={(value) => set("violenciaFisica", value)} />}
      {patrimony.violenciaFisica !== undefined && <ToggleQuestion legend="¿Hay intimidación?" value={patrimony.intimidacion} onChange={(value) => set("intimidacion", value)} />}
      {patrimony.violenciaFisica !== undefined && patrimony.intimidacion !== undefined && ((patrimony.violenciaFisica || patrimony.intimidacion) ? <><fieldset className="sp-choice"><legend>Momento de la violencia o intimidación</legend>{[["apoderamiento", "Para obtener la cosa"], ["conservar", "Para conservarla"], ["huida", "Durante la huida"], ["auxiliador", "Contra quien auxilia"], ["perseguidor", "Contra quien persigue"], ["no_determinado", "No determinado"]].map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.momentoViolencia === value} onChange={() => set("momentoViolencia", value as PatrimonyFacts["momentoViolencia"])} /> {label}</label>)}</fieldset>{patrimony.momentoViolencia && yesNo("¿Está conectada con obtener o conservar la cosa, huir o vencer a quien auxilia o persigue?", "conexionViolenciaApoderamiento")}{patrimony.conexionViolenciaApoderamiento === true && <>{yesNo("¿Hay arma o medio peligroso presente?", "armaPresente")}{patrimony.armaPresente && yesNo("¿Se usa efectivamente el arma o medio peligroso?", "armaUsada")}{yesNo("¿Alguien presenta o refiere lesiones?", "lesionAutonoma")}{yesNo("¿Hubo otras amenazas o imposiciones separadas del intento de llevarse la cosa?", "amenazaCoaccionAutonoma")}</>}</> : <fieldset className="sp-choice"><legend>Fuerza material para acceder o abandonar</legend>{[["ninguna", "Ninguna"], ["escalamiento", "Entró trepando o superando una barrera por un acceso no destinado a entrar"], ["rotura_acceso", "Rotura de acceso"], ["fractura_contenedor", "Fractura de mueble o recipiente"], ["cerradura_claves", "Forzamiento de cerradura o claves"], ["llave_falsa", "Usó ganzúa, llave sustraída/perdida o copia sin autorización del titular"], ["alarma_acceso_salida", "Inutilización de alarma de acceso o salida"], ["llave_entregada_legitima", "Llave entregada legítimamente"], ["escalamiento_dudoso", "No se conoce cómo superó la barrera o accedió"], ["no_determinada", "No determinada"]].map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.fuerza === value} onChange={() => set("fuerza", value as PatrimonyFacts["fuerza"])} /> {label}</label>)}</fieldset>)}
      {patrimony.fuerza && patrimony.fuerza !== "ninguna" && <fieldset className="sp-choice"><legend>Lugar</legend>{[["morada", "Morada, aunque esté temporalmente vacía"], ["local_abierto", "Local abierto al público"], ["local_fuera_horario", "Local fuera del horario de apertura"], ["dependencia", "Dependencia de casa o local"], ["otro", "Otro lugar"], ["no_determinado", "No determinado"]].map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.tipoLugar === value} onChange={() => set("tipoLugar", value as PatrimonyFacts["tipoLugar"])} /> {label}</label>)}</fieldset>}
      {(patrimony.fuerza === "ninguna" || patrimony.conexionViolenciaApoderamiento === true) && <><MoneyQuestion facts={patrimony} set={set} />{patrimony.cuantiaAcreditada === true && <>{yesNo("¿Se neutraliza un dispositivo antihurto instalado en la propia cosa?", "dispositivoAntihurtoEnCosaNeutralizado")}{yesNo("¿Es un teléfono móvil, tableta, ordenador u otro dispositivo portátil para almacenar o comunicar datos?", "telefonoODispositivo235")}{patrimony.telefonoODispositivo235 && yesNo("¿Es una existencia destinada a venta, almacenamiento o exposición comercial?", "existenciaComercialVentaAlmacenExposicion")}</>}</>}
    </>}
    {patrimony.hechoPrincipal === "recepcion" && patrimony.titularidad === "ajena" && <>
      <fieldset className="sp-choice"><legend>¿Cómo llegó la cosa a poder del autor?</legend>{[["autor_entrega_legitima", "Entrega legítima"], ["autor_acceso_material", "Mero acceso material o laboral"], ["autor_facultades_administracion", "Con facultades de administración"], ["victima_titular", "Seguía en posesión del titular"], ["tercero", "Por un tercero"], ["no_determinada", "No determinado"]].map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.posesionPrevia === value} onChange={() => set("posesionPrevia", value as PatrimonyFacts["posesionPrevia"])} /> {label}</label>)}</fieldset>
      {patrimony.posesionPrevia && yesNo("¿La víctima entregó el bien o dinero porque creyó una información falsa que le dio esa persona?", "enganoPrevioActoDisposicion")}{patrimony.enganoPrevioActoDisposicion === false && <>{yesNo("¿Existía obligación de devolver o entregar?", "obligacionDevolverEntregar")}{yesNo("¿Tenía facultades de administración?", "facultadesAdministracion")}{patrimony.facultadesAdministracion && yesNo("¿Dispuso de bienes o dinero fuera de lo autorizado y causó una pérdida al titular?", "excesoFacultadesConPerjuicio")}{yesNo("¿Se apropió o negó haber recibido la cosa?", "conductaApropiacionONegacion")}{yesNo("¿Se quedó con una cosa encontrada o recibida por error, sin entrega previa para custodiarla o devolverla?", "viaApropiacionFuera253")}{(patrimony.conductaApropiacionONegacion || patrimony.viaApropiacionFuera253 || patrimony.excesoFacultadesConPerjuicio) && <MoneyQuestion facts={patrimony} set={set} />}</>}
    </>}
     {patrimony.hechoPrincipal === "danos" && patrimony.titularidad === "ajena" && <>
       <fieldset className="sp-choice"><legend>Intencionalidad</legend>{[["deliberado", "Daño deliberado"], ["imprudente_accidental", "Imprudente o accidental"], ["no_determinado", "No determinada"]].map(([value, label]) => <label key={value}><input type="radio" checked={patrimony.intencionalidadDano === value} onChange={() => set("intencionalidadDano", value as PatrimonyFacts["intencionalidadDano"])} /> {label}</label>)}</fieldset>
       {patrimony.intencionalidadDano && yesNo("¿Se borraron, alteraron o bloquearon datos, programas o un sistema informático?", "danoInformatico")}
       {patrimony.danoInformatico === false && <>
         <MoneyQuestion facts={patrimony} set={set} />
         {patrimony.cuantiaAcreditada === true && <>
           {yesNo("¿Afecta a bien de dominio o uso público o comunal?", "bienDominioUsoPublicoComunal")}
           {yesNo("¿Se emplea medio destructivo o se genera peligro para personas?", "medioDestructivoOPeligroPersonas")}
           {patrimony.medioDestructivoOPeligroPersonas === true && <>
             <ChoiceQuestion legend="¿Qué medio se documenta?" value={patrimony.medioDano} options={damageMediumOptions} onChange={(value) => set("medioDano", value as PatrimonyFacts["medioDano"])} />
             <ToggleQuestion legend="¿Se documenta peligro concreto para la vida o integridad de personas?" value={patrimony.peligroVidaIntegridad} onChange={(value) => set("peligroVidaIntegridad", value)} />
             <ChoiceQuestion legend="¿Qué tipo de bien resulta afectado?" value={patrimony.bienEspecial266} options={specialDamageAssetOptions} onChange={(value) => set("bienEspecial266", value as PatrimonyFacts["bienEspecial266"])} />{patrimony.bienEspecial266 === "militar_265" && <ToggleQuestion legend="¿Se destruyó, dañó gravemente o inutilizó para el servicio el recurso militar o de las fuerzas de seguridad?" value={patrimony.danoGraveOInutilizacionMilitar} onChange={(value) => set("danoGraveOInutilizacionMilitar", value)} />}{patrimony.bienEspecial266 === "servicio_560" && <ToggleQuestion legend="¿Se documenta interrupción, obstaculización o destrucción de telecomunicaciones/correspondencia, daño en vía férrea o grave afección al suministro de agua, gas o electricidad?" value={patrimony.interrupcionObstaculizacionServicio} onChange={(value) => set("interrupcionObstaculizacionServicio", value)} />}
           </>}
         </>}
       </>}
     </>}
    {patrimony.titularidad === "ajena" && patrimony.hechoPrincipal !== "danos" && <ChoiceQuestion legend="¿Llegó a disponer de la cosa fuera del control de su titular?" value={patrimony.gradoEjecucion} options={[["consumado", "Sí, pudo disponer de ella"], ["tentativa", "Se inició la acción pero se impidió que llegara a disponer de ella"], ["no_determinado", "No se conoce todavía"]]} onChange={(value) => set("gradoEjecucion", value as PatrimonyFacts["gradoEjecucion"])} />}
    {outcome.procesal && <ProcessualControls flagrante={flagrante} setFlagrante={setFlagrante} facts={processFacts} setFacts={setProcessFacts} minor={minor} complaintRequired={complaintRequired} />}
    <PatrimonyOutcomeView outcome={outcome} showProcess onNavigate={onNavigate} />
  </>;
}

function MoneyQuestion({ facts, set }: { facts: PatrimonyFacts; set: <K extends keyof PatrimonyFacts>(key: K, value: PatrimonyFacts[K]) => void }) { return <fieldset className="sp-choice"><legend>Cuantía o perjuicio</legend><label className="sp-subchoice">Importe en euros <input type="number" min="0" step="0.01" value={facts.cuantia ?? ""} onChange={(event) => set("cuantia", event.target.value === "" ? undefined : Number(event.target.value))} /></label><ToggleQuestion legend="¿El importe está respaldado por ticket, factura, documento o una comprobación disponible?" value={facts.cuantiaAcreditada} onChange={(value) => set("cuantiaAcreditada", value)} /></fieldset> }

function PatrimonyOutcomeView({ outcome, showProcess, onNavigate }: { outcome: PatrimonyOutcome; showProcess: boolean; onNavigate: (id: string) => void }) {
  return <>
    <ResultCard title={outcome.resultado} norma={outcome.norma ?? "Datos de la intervención"} clasificacion={outcome.gravedad} text={outcome.hecho} />
    {outcome.procesal && showProcess && <AuthorSituation decision={outcome.procesal} explain={false} />}
    {outcome.procesal && showProcess ? <Continuation decision={outcome.procesal} additionalItems={outcome.actuacion} /> : <OperationalSection title="Actuación inmediata" items={outcome.actuacion} />}
    {outcome.procesal && showProcess && <ProcessualExplanation decision={outcome.procesal} />}
    <OperationalSection title="Por qué" items={outcome.porQue} />
    <PendingDetails text={outcome.falta} />
    {outcome.grado && <OperationalSection title="Grado de ejecución" items={[outcome.grado]} />}
    {outcome.exencion && <div className="sp-highlight neutral"><strong>{outcome.exencion.titulo}</strong><p>{outcome.exencion.fundamento}</p></div>}
    <OperationalSection title="Avisos" items={outcome.avisos} />
    {outcome.conexiones.length > 0 && <section className="sp-section"><h3>Conexiones</h3><div className="sp-connections">{outcome.conexiones.map((connection) => <button key={connection.conceptId} onClick={() => onNavigate(connection.conceptId)}><span className="sp-connection-icon" aria-hidden="true">{publicSecurityConceptIcon(connection.conceptId)}</span><span><strong>{connection.etiqueta}</strong><small>{connection.motivo}</small></span><b aria-hidden="true">›</b></button>)}</div></section>}
    {outcome.supuestoPenalId && <ExportPenaltyFramework supuestoPenalId={outcome.supuestoPenalId} />}
    <LegalFoundation normas={[outcome.norma ?? "Datos de la intervención"]} detalle="Calificación orientativa basada solo en los hechos indicados; documentar los extremos pendientes." />
  </>;
}

function ResolvedOutcome({ result, drug = false, weapon, showFoundation = true, showProcessual }: { result: AuthorityOutcome | DrugOutcome | WeaponOutcome; drug?: boolean; weapon?: "weapon" | "object"; showFoundation?: boolean; showProcessual?: boolean }) {
  const hasProcessualOutput = Boolean(result.situacion || result.detencion);
  const visibleProcessual = showProcessual ?? (!("processualAnswered" in result) || Boolean(result.processualAnswered));
  const relevantObject = weapon === "object" && "kind" in result && !["sin_conclusion_automatica", "valoracion_especifica"].includes(result.kind);
  const actions = result.actuacion.filter((item) => !isContinuationAction(item));
  return <><ResultCard title={result.titulo} norma={result.norma} clasificacion={result.clasificacion} range={"rango" in result ? result.rango : undefined} text={result.porQue} />{hasProcessualOutput && visibleProcessual ? <><AuthorSituation decision={result} explain={false} /><Continuation decision={result} additionalItems={actions} /><ProcessualExplanation decision={result} /></> : <OperationalSection title="Actuación inmediata" items={actions} />}{weapon === "weapon" && "kind" in result && result.kind === "penal" && <EffectsCommon weapon />}{relevantObject && <EffectsCommon object />}{drug && <CommonProcessual showSubstance />}<PendingDetails text={result.incertidumbre} />{result.supuestoPenalId && <ExportPenaltyFramework supuestoPenalId={result.supuestoPenalId} />}{showFoundation && <LegalFoundation normas={[result.norma]} detalle={"frontera" in result ? result.frontera : "No se usa una cantidad, ni un número de indicios, como frontera automática."} />}</>;
}

function ResultCard({ title, norma, clasificacion, range, text, showText = true, referenciasProcesales }: { title: string; norma: string; clasificacion?: string; range?: string; text: string; showText?: boolean; referenciasProcesales?: UsoReferenciaProcesal[] }) { return <section className="sp-result"><span>{title}</span><h3>{norma}</h3>{clasificacion && <strong className={clasificacion.includes("DELITO") ? "sp-pill penal" : "sp-pill"}>{clasificacion}</strong>}{range && <p className="sp-range">Rango legal: <strong>{range}</strong></p>}{showText && <p>{text}</p>}{range && <p>La LO 4/2015 califica esta conducta como infracción grave y prevé una sanción de entre 601 y 30.000 euros. La cuantía concreta será determinada por el órgano sancionador competente.</p>}<ContextualProcessualHelp usos={referenciasProcesales} /></section> }
function OperationalSection({ title, items }: { title: string; items: string[] }) { if (!items.length) return null; return <section className="sp-section"><h3>{title}</h3><ul>{items.map((item) => <li key={item}>{item}</li>)}</ul></section> }
function EffectsCommon({ weapon = false, object = false }: { weapon?: boolean; object?: boolean }) { return <CollapsibleSection title={weapon || object ? "Efectos / instrumentos relacionados" : "Efectos / custodia"}><Checklist items={weapon ? ["Arma intervenida, ocupada y custodiada.", "Lugar exacto de intervención y persona que disponía de ella.", "Estado, características y relación objetiva con los hechos."] : object ? ["Objeto asegurado o intervenido cuando proceda por su relación con los hechos.", "Lugar exacto y persona que disponía de él.", "Estado, características y relación objetiva con la conducta."] : seguridadPublica.comunes.efectos} note={weapon || object ? "La intervención y custodia, cuando procedan, se incorporan a las diligencias y a la coordinación con CNP." : seguridadPublica.comunes.efectos_aviso} /></CollapsibleSection> }
export function ProcessualControls({ flagrante, setFlagrante, facts, setFacts, minor = false, complaintRequired = false, complaintManagedExternally = false, ageManagedExternally = false }: { flagrante: boolean | undefined; setFlagrante: (value: boolean) => void; facts: ProcessualFactsForm; setFacts: Dispatch<SetStateAction<ProcessualFactsForm>>; minor?: boolean; complaintRequired?: boolean; complaintManagedExternally?: boolean; ageManagedExternally?: boolean }) {
  const set = <K extends keyof ProcessualFactsForm>(key: K, value: ProcessualFactsForm[K]) => setFacts((current) => ({ ...current, [key]: value }));
  const chooseFlagrancy = (value: boolean) => {
    setFlagrante(value);
    setFacts((current) => ({ autorMayorEdad: current.autorMayorEdad, denunciaOQuerella: current.denunciaOQuerella, procedibilidad: current.procedibilidad }));
  };
  const commonQuestions = <>{!ageManagedExternally && <ToggleQuestion legend="¿El presunto autor tenía 18 años o más?" value={facts.autorMayorEdad} onChange={(value) => set("autorMayorEdad", value)} />}{complaintRequired && !complaintManagedExternally && <ToggleQuestion legend="¿Consta denuncia de la víctima o representante, o actuación de Fiscalía?" value={facts.denunciaOQuerella} onChange={(value) => set("denunciaOQuerella", value)} />}</>;
  if (minor) return <fieldset className="sp-choice sp-processual-question"><legend>Identificación y comparecencia</legend>{commonQuestions}<ToggleQuestion legend="¿Tiene domicilio conocido y verificable?" value={facts.domicilioConocido} onChange={(value) => set("domicilioConocido", value)} /></fieldset>;
  const allRisks = facts.indiciosHechoSuficientes === true && facts.indiciosParticipacionSuficientes === true;
  return <fieldset className="sp-choice sp-processual-question"><legend>Hechos procesales observados</legend>{commonQuestions}<strong>¿La persona ha sido sorprendida durante la comisión del hecho o inmediatamente después?</strong><label><input type="radio" checked={flagrante === true} onChange={() => chooseFlagrancy(true)} /> Sí</label><label><input type="radio" checked={flagrante === false} onChange={() => chooseFlagrancy(false)} /> No</label>{flagrante === false && <div className="sp-nested-question"><ToggleQuestion legend="¿Hay relato concreto corroborado, testigos, imágenes o vestigios del hecho?" value={facts.indiciosHechoSuficientes} onChange={(value) => set("indiciosHechoSuficientes", value)} />{facts.indiciosHechoSuficientes === true && <ToggleQuestion legend="¿Los testigos, imágenes, efectos u otros indicios vinculan a esta persona con el hecho?" value={facts.indiciosParticipacionSuficientes} onChange={(value) => set("indiciosParticipacionSuficientes", value)} />}{allRisks && <><p className="sp-question-help">Marca cada circunstancia factual. La ausencia de flagrancia no decide por sí sola la detención.</p><ToggleQuestion legend="¿Ha intentado fugarse o eludir la actuación?" value={facts.intentoFugaElusion} onChange={(value) => set("intentoFugaElusion", value)} /><ToggleQuestion legend="¿La identidad o el domicilio han podido verificarse?" value={invertBooleanAnswer(facts.identidadODomicilioNoVerificables)} onChange={(value) => set("identidadODomicilioNoVerificables", invertBooleanAnswer(value))} /><ToggleQuestion legend="¿Ha intentado ocultar, alterar o destruir pruebas concretas?" value={facts.riesgoOcultacionPruebas} onChange={(value) => set("riesgoOcultacionPruebas", value)} /><ToggleQuestion legend="¿Ha amenazado o intentado acercarse a la víctima o a testigos?" value={facts.riesgoConcretoVictimaTestigos} onChange={(value) => set("riesgoConcretoVictimaTestigos", value)} /></>}</div>}</fieldset>;
}

export function ExportPenaltyFramework({ supuestoPenalId }: { supuestoPenalId: SupuestoPenalId }) {
  const entry: SupuestoPenal = catalogoPenal[supuestoPenalId];
  return <details className="sp-common sp-penalty-framework"><summary>Marco penal y fuente oficial · {entry.articulo} · {entry.subtipo}</summary><p>{entry.descripcion}</p>
    {entry.condiciones.length > 0 && <OperationalSection title="Condiciones del supuesto" items={entry.condiciones} />}
    <p><strong>Penas abstractas:</strong> {describeRegime(entry.penas)}</p>
    {entry.penasCondicionales?.map((conditional) => <p key={conditional.condicion}><strong>{conditional.condicion}</strong> {describeRegime(conditional.penas)}</p>)}
    {entry.advertencias.length > 0 && <OperationalSection title="Límites de esta referencia" items={entry.advertencias} />}
    <ul>{entry.fuentesOficiales.map((url) => <li key={url}><a href={url} target="_blank" rel="noreferrer">Código Penal consolidado · BOE ↗</a></li>)}</ul>
  </details>;
}
export { ExportPenaltyFramework as PenaltyFramework };

function describeRegime(regime: RegimenPenas): string {
  if (regime.tipo === "pendiente") return "Pendiente de concretar";
  if (regime.tipo === "accesoria") return "Pena accesoria";
  if (regime.tipo === "conjuntas" || regime.tipo === "alternativas") return `(${regime.penas.map(describeRegime).join(regime.tipo === "conjuntas" ? " y " : " o ")})`;
  if (regime.tipo === "mitad_superior" || regime.tipo === "superior_grado") {
    const exact = transformarMarcoPenal(regime.base, regime.tipo);
    return exact ? describeRegime(exact) : "Pena pendiente de concreción";
  }
  if (regime.tipo !== "pena") return "Marco penal pendiente de descripción";
  const { pena } = regime;
  if (pena.tipo === "multa_proporcional") return pena.factorMinimo !== undefined && pena.factorMaximo !== undefined ? `multa proporcional de ${pena.factorMinimo} a ${pena.factorMaximo} veces el ${pena.baseEconomica}` : "multa proporcional";
  if (pena.tipo === "prision_permanente_revisable") return "prisión permanente revisable";
  if (!("minimo" in pena)) return pena.tipo.replaceAll("_", " ");
  const format = (duration: typeof pena.minimo) => [duration.valor, duration.unidad === "anios" ? "años" : duration.unidad, duration.diasAdicionales ? `y ${duration.diasAdicionales} ${duration.diasAdicionales === 1 ? "día" : "días"}` : ""].filter(Boolean).join(" ");
  const names: Record<string, string> = { prision: "prisión", tbc: "trabajos en beneficio de la comunidad", localizacion: "localización permanente", armas: "privación del derecho a tenencia y porte de armas", conduccion: "privación del derecho a conducir", animales: "inhabilitación para actividades relacionadas con animales y para su tenencia", inhabilitacion_especial: "inhabilitación especial", aproximacion: "prohibición de aproximación", comunicacion: "prohibición de comunicación", residencia: "privación del derecho a residir o acudir a determinados lugares", suspension: "suspensión de empleo o cargo público" };
  const label = names[pena.tipo] ?? pena.tipo.replaceAll("_", " ");
  return `${label} de ${format(pena.minimo)} a ${format(pena.maximo)}`;
}
export function ContextualProcessualHelp({ usos }: { usos?: UsoReferenciaProcesal[] }) { if (!usos?.length) return null; return <div className="sp-processual-references" aria-label="Explicación de referencias procesales">{usos.map((uso) => { const referencia = obtenerReferenciaProcesal(uso.id); return <details className="sp-legal-help" key={uso.id}><summary><span>{referencia.articulo}</span><b aria-hidden="true">ⓘ</b><em>¿Por qué?</em></summary><div className="sp-legal-help-body"><h4>Artículo y materia</h4><p><strong>{referencia.articulo} — {referencia.titulo}</strong></p><h4>Qué establece</h4><blockquote>{referencia.fragmentoLegal}</blockquote><h4>Por qué se aplica en este caso</h4><p>{uso.aplicacionAlCaso}</p><h4>Conclusión</h4><p className="sp-legal-scope">{uso.conclusion}</p><a href={referencia.fuenteOficial} target="_blank" rel="noreferrer">Fuente oficial: BOE ↗</a><small>{referencia.version}</small></div></details>; })}</div> }
type VisibleDecision = { situacion?: string; detencion?: string; escenarioProcesal?: string; fundamentoDetencion?: string; razonamientoProcesal?: RazonamientoProcesal; referenciasProcesales?: UsoReferenciaProcesal[] };
export function ProcessualExplanation({ decision }: { decision: VisibleDecision }) {
  const fundamento = decision.razonamientoProcesal ? redactarRazonamientoProcesal(decision.razonamientoProcesal) : decision.fundamentoDetencion;
  return <>{fundamento && <details className="sp-common sp-decision-reason"><summary>ⓘ ¿Por qué?</summary><p>{fundamento}</p><ContextualProcessualHelp usos={decision.referenciasProcesales} /></details>}</>;
}
export function PendingDetails({ text }: { text?: string }) { return text ? <section className="sp-section sp-pending-detail"><h3>Pendiente de determinación posterior</h3><p>{text}</p></section> : null; }
export function AuthorSituation({ decision, explain = true }: { decision: VisibleDecision; explain?: boolean }) {
  if (!decision.situacion || !decision.detencion) return null;
  const output = decision.situacion === "DETENIDO" ? "🔴 DETENER" : decision.situacion === "INVESTIGADO NO DETENIDO" ? "🟠 INVESTIGADO NO DETENIDO" : decision.situacion === "NO DETENER TODAVÍA — INVESTIGAR" ? "🟡 DILIGENCIAS Y COMPROBACIONES" : decision.situacion;
  const tone = decision.situacion === "DETENIDO" ? "detain" : decision.situacion === "INVESTIGADO NO DETENIDO" ? "investigate" : "prevent";
  return <section className="sp-section sp-processual-output"><h3>SITUACIÓN PROCESAL</h3><div className={"sp-decision-banner " + tone}><span aria-hidden="true" /><strong>{output}</strong><small>{decision.detencion === "NO APLICAR MOTOR ADULTO" ? "Aplicar procedimiento de menores" : "Detención: " + (decision.detencion === "SÍ" ? "sí" : "no")}</small></div>{explain && <ProcessualExplanation decision={decision} />}</section>;
}

function Continuation({ decision, additionalItems = [] }: { decision: { situacion?: string }; additionalItems?: string[] }) { if (!decision.situacion) return null; const next = decision.situacion === "DETENIDO" ? ["Informar de derechos y garantías al detenido.", "Solicitar presencia de CNP en el lugar.", "Entregar persona y actuaciones a CNP."] : decision.situacion === "INVESTIGADO NO DETENIDO" ? ["Informar de hechos y derechos.", "Coordinar con CNP la continuación y citación.", "Comparecer posteriormente cuando corresponda."] : decision.situacion === "RUTA DE RESPONSABILIDAD PENAL DE MENORES" ? ["Activar el procedimiento específico de responsabilidad penal de menores y coordinar con la unidad competente."] : ["Continuar diligencias y comprobaciones a prevención.", "Comunicar las actuaciones a CNP o unidad competente."]; return <OperationalSection title="CONTINUACIÓN OPERATIVA" items={uniqueItems([...additionalItems, ...next])} /> }
function LegalFoundation({ normas, detalle }: { normas: string[]; detalle?: string }) { return <div className="sp-common"><CollapsibleSection title="Fundamento jurídico"><Checklist items={uniqueItems(normas)} />{detalle && <p>{detalle}</p>}</CollapsibleSection></div> }
function CommonProcessual({ showSubstance = false }: { showSubstance?: boolean }) { if (!showSubstance) return null; return <div className="sp-common"><CollapsibleSection title="Aprehensión de sustancia"><Checklist items={seguridadPublica.comunes.aprehension} /></CollapsibleSection></div> }
function Checklist({ items, title, note }: { items: string[]; title?: string; note?: string }) { return <div className="sp-checklist">{title && <h4>{title}</h4>}<ul>{items.map((item) => <li key={item}>{item}</li>)}</ul>{note && <p className="sp-note">{note}</p>}</div> }
const normalise = (value: string) => value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();

const uniqueItems = (items: string[]) => [...new Set(items)];
const isContinuationAction = (item: string) => /coordinar continuacion|continuacion.*CNP|presentar.*CNP|continuacion y citacion/i.test(normalise(item));
const isAttentionAction = (item: string) => /evitar interrogatorios|repeticiones innecesarias|no impide continuar/i.test(normalise(item));
const isIncidentAttention = (item: PublicSafetyOutcome["resultados"][number]) =>
  /DENUNCIA DE LA V[ÍI]CTIMA|NO VALORAR [ÚU]NICAMENTE COMO LESIONES|SUMISI[ÓO]N O VULNERABILIDAD QU[ÍI]MICA|V[ÍI]CTIMA MENOR DE 16 A[ÑN]OS/i.test(item.titulo);
