const relationThreatHarmOptions: Array<[string, string]> = [["entidad_delictiva", "Anuncia matar, causar lesiones, forzar actos sexuales, privar de libertad o destruir bienes"], ["menor_entidad", "Expresión intimidatoria aislada sin concretar uno de esos daños"], ["no_delictivo", "Anuncia despedir, romper una relación o divulgar información lícita"], ["no_precisado", "No puede concretarse todavía"]];
